import{_ as d,c as e,o,am as r}from"./chunks/framework.BJtUKP3U.js";const s=JSON.parse('{"title":"宿主输入","description":"","frontmatter":{"prev":{"text":"接口参考","link":"/docs/pogget/custom-vina/reference"},"next":{"text":"内部动作","link":"/docs/pogget/custom-vina/actions"}},"headers":[],"relativePath":"docs/pogget/custom-vina/inputs.md","filePath":"docs/pogget/custom-vina/inputs.md"}'),c={name:"docs/pogget/custom-vina/inputs.md"};function g(i,t,a,n,p,l){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="宿主输入" tabindex="-1">宿主输入 <a class="header-anchor" href="#宿主输入" aria-label="Permalink to &quot;宿主输入&quot;">​</a></h1><p>宿主输入由 Pogget 提供，在表达式中用 <code>${完整路径}</code> 读取，例如 <code>${pogget.width}</code>。以下按用途列出当前可用输入，<strong>均为只读事实</strong>；不能通过在预设里写同名属性来修改真实业务状态。</p><p>表中的“数值”默认单位为 DIP，“颜色”是 COLORREF。进度按对应原生动画器提交，不应一律假定为 <code>0..1</code>；自定义视图的 <code>self.hoverProgress</code> 才明确为 <code>0..1</code>。</p><h2 id="收纳盒与主题" tabindex="-1">收纳盒与主题 <a class="header-anchor" href="#收纳盒与主题" aria-label="Permalink to &quot;收纳盒与主题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.width</code>、<code>pogget.height</code></td><td>数值；收纳盒当前宽高</td></tr><tr><td><code>pogget.title</code></td><td>文本；收纳盒标题</td></tr><tr><td><code>pogget.isListView</code></td><td>布尔；是否为列表视图</td></tr><tr><td><code>pogget.locked</code></td><td>布尔；布局是否锁定，不表示位置也锁定</td></tr><tr><td><code>pogget.collapsed</code></td><td>布尔；普通折叠状态；悬停折叠需结合下表状态判断</td></tr><tr><td><code>pogget.upward</code></td><td>布尔；是否向上展开</td></tr><tr><td><code>pogget.cornerRadius</code></td><td>数值；收纳盒配置的圆角</td></tr><tr><td><code>pogget.nativeCornerRadius</code></td><td>数值；原生窗口实际自定义圆角</td></tr><tr><td><code>pogget.mode</code></td><td>数值；兼容/渲染层，<code>0..4</code> 对应默认、静态、模糊、透明、扩展</td></tr><tr><td><code>pogget.frame</code></td><td>数值；透明边框模式，<code>0..3</code> 对应无、画布、原生、高光</td></tr><tr><td><code>pogget.staticMaterial</code></td><td>布尔；是否启用 D3D11 静态材质层</td></tr><tr><td><code>pogget.layoutHidden</code></td><td>布尔；当前原生布局隐藏策略的结果，用于标题与内容占位</td></tr><tr><td><code>pogget.shadowPadding</code></td><td>布尔；窗口是否启用阴影留白</td></tr><tr><td><code>pogget.theme.darknight</code></td><td>颜色；当前主题的深层背景色</td></tr><tr><td><code>pogget.theme.midnight</code></td><td>颜色；当前主题的普通表面色</td></tr><tr><td><code>pogget.theme.midnightplus</code></td><td>颜色；当前主题的次级表面色</td></tr><tr><td><code>pogget.theme.white</code></td><td>颜色；当前主题的前景色，会随主题变化，不一定是纯白</td></tr><tr><td><code>pogget.theme.darken</code></td><td>颜色；当前主题的暗部色</td></tr><tr><td><code>pogget.theme.accent</code></td><td>颜色；当前主题强调色</td></tr><tr><td><code>pogget.theme.monochrome</code></td><td>布尔；当前主题的背景红绿通道相等这一原生判定结果</td></tr></tbody></table><h2 id="标题与折叠" tabindex="-1">标题与折叠 <a class="header-anchor" href="#标题与折叠" aria-label="Permalink to &quot;标题与折叠&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.titleY</code>、<code>pogget.titleHeight</code></td><td>数值；当前标题纵坐标与高度</td></tr><tr><td><code>pogget.collapsedHeight</code></td><td>数值；原生折叠高度</td></tr><tr><td><code>pogget.titleTextWidth</code></td><td>数值；标题文字测量宽度</td></tr><tr><td><code>pogget.titleHidden</code></td><td>布尔；标题当前是否隐藏</td></tr><tr><td><code>pogget.titleExtension</code></td><td>数值；标题附加占位高度</td></tr><tr><td><code>pogget.titleVariant</code></td><td>数值；当前标题样式分支</td></tr><tr><td><code>pogget.titleProgress</code></td><td>数值；标题折叠动画进度</td></tr><tr><td><code>pogget.titleTransitioning</code></td><td>布尔；标题是否正在切换样式</td></tr><tr><td><code>pogget.titleOffsetAnim</code></td><td>数值；标题显示/隐藏的动画偏移</td></tr><tr><td><code>pogget.searching</code></td><td>布尔；标题当前搜索状态</td></tr><tr><td><code>pogget.searchExpand</code></td><td>数值；标题搜索展开动画值</td></tr><tr><td><code>pogget.titleColor</code></td><td>颜色；当前标题表面的有效颜色</td></tr><tr><td><code>pogget.titleBorderColor</code></td><td>颜色；当前标题边框色</td></tr><tr><td><code>pogget.titleCustomColor</code></td><td>布尔；标题是否使用主题色以外的来源，包括标签色和自定义色</td></tr><tr><td><code>pogget.buttonColor</code></td><td>颜色；标题按钮的有效前景色</td></tr><tr><td><code>pogget.hoverCollapsed</code></td><td>布尔；是否处于悬停展开式折叠模式</td></tr><tr><td><code>pogget.hoverExpanded</code></td><td>布尔；悬停折叠的收纳盒当前是否展开</td></tr><tr><td><code>pogget.hoverExpandingAnimation</code></td><td>布尔；是否正在进行悬停展开动画</td></tr><tr><td><code>pogget.temporaryTopmost</code></td><td>布尔；是否处于临时置顶会话</td></tr><tr><td><code>pogget.pinProgress</code></td><td>数值；固定按钮胶囊的动画进度</td></tr><tr><td><code>pogget.titleFluidX</code>、<code>pogget.titleFluidY</code></td><td>数值；标题过渡动画当前表面的起点</td></tr><tr><td><code>pogget.titleFluidWidth</code>、<code>pogget.titleFluidHeight</code></td><td>数值；标题过渡动画当前表面的宽高</td></tr><tr><td><code>pogget.titleFluidRadius</code></td><td>数值；标题过渡动画当前圆角</td></tr><tr><td><code>pogget.titleFluidShadowY</code></td><td>数值；标题过渡动画当前阴影纵偏移</td></tr><tr><td><code>pogget.titleFluidShadowAlpha</code></td><td>数值；标题过渡动画当前阴影不透明度</td></tr><tr><td><code>pogget.titleFluidBorderAlpha</code></td><td>数值；标题过渡动画当前边框不透明度</td></tr></tbody></table><h3 id="原生按钮反馈" tabindex="-1">原生按钮反馈 <a class="header-anchor" href="#原生按钮反馈" aria-label="Permalink to &quot;原生按钮反馈&quot;">​</a></h3><p>以下四组完整路径均可读取。<code>hover</code> 是原生按钮反馈值；<code>pressScale</code>、<code>holdScale</code> 是缩放，<code>holdY</code> 是长按位移，<code>opacity</code> 是按钮不透明度。</p><table tabindex="0"><thead><tr><th>输入组</th><th>用途</th></tr></thead><tbody><tr><td><code>pogget.titleCollapse.hover</code>、<code>pogget.titleCollapse.pressScale</code>、<code>pogget.titleCollapse.holdScale</code>、<code>pogget.titleCollapse.holdY</code>、<code>pogget.titleCollapse.opacity</code></td><td>折叠按钮反馈</td></tr><tr><td><code>pogget.titleMore.hover</code>、<code>pogget.titleMore.pressScale</code>、<code>pogget.titleMore.holdScale</code>、<code>pogget.titleMore.holdY</code>、<code>pogget.titleMore.opacity</code></td><td>更多按钮反馈</td></tr><tr><td><code>pogget.titlePin.hover</code>、<code>pogget.titlePin.pressScale</code>、<code>pogget.titlePin.holdScale</code>、<code>pogget.titlePin.holdY</code>、<code>pogget.titlePin.opacity</code></td><td>固定按钮反馈</td></tr><tr><td><code>pogget.titleSearchOptions.hover</code>、<code>pogget.titleSearchOptions.pressScale</code>、<code>pogget.titleSearchOptions.holdScale</code>、<code>pogget.titleSearchOptions.holdY</code>、<code>pogget.titleSearchOptions.opacity</code></td><td>搜索选项按钮反馈</td></tr></tbody></table><h3 id="标题标签" tabindex="-1">标题标签 <a class="header-anchor" href="#标题标签" aria-label="Permalink to &quot;标题标签&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.tag.text</code>、<code>pogget.tag.oldText</code></td><td>文本；当前文字与切换前文字</td></tr><tr><td><code>pogget.tag.color</code></td><td>颜色；标签源颜色</td></tr><tr><td><code>pogget.tag.active</code></td><td>布尔；标签是否可交互</td></tr><tr><td><code>pogget.tag.emphasized</code></td><td>布尔；标签强调状态</td></tr><tr><td><code>pogget.tag.measuredWidth</code></td><td>数值；标签文字测量宽度</td></tr><tr><td><code>pogget.tag.hover</code>、<code>pogget.tag.push</code></td><td>数值；原生标签悬停、按压进度</td></tr><tr><td><code>pogget.tag.textProgress</code></td><td>数值；新旧文字切换进度</td></tr><tr><td><code>pogget.tag.direction</code></td><td>数值；文字切换动画方向</td></tr></tbody></table><h2 id="合并标签页-pogget-tab" tabindex="-1">合并标签页 pogget.tab <a class="header-anchor" href="#合并标签页-pogget-tab" aria-label="Permalink to &quot;合并标签页 pogget.tab&quot;">​</a></h2><p>这些输入在每个标签页的绘制阶段更新，描述<strong>当前项</strong>。</p><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.tab.index</code>、<code>pogget.tab.count</code></td><td>数值；当前成员序号与总数</td></tr><tr><td><code>pogget.tab.cursor</code></td><td>数值；布局遍历到当前成员时的横向游标</td></tr><tr><td><code>pogget.tab.totalWeight</code></td><td>数值；全部标签的累计布局权重</td></tr><tr><td><code>pogget.tab.selected</code></td><td>布尔；当前成员是否被选中</td></tr><tr><td><code>pogget.tab.drawIsland</code></td><td>布尔；当前绘制调用是否要求绘制背景岛</td></tr><tr><td><code>pogget.tab.accent</code>、<code>pogget.tab.textColor</code></td><td>颜色；当前成员强调色与文字色</td></tr><tr><td><code>pogget.tab.text</code></td><td>文本；当前标签标题</td></tr><tr><td><code>pogget.tab.displayUnits</code></td><td>数值；当前标签的 Unicode 显示单位数</td></tr><tr><td><code>pogget.tab.x</code>、<code>pogget.tab.y</code></td><td>数值；当前标签绘制位置</td></tr><tr><td><code>pogget.tab.width</code>、<code>pogget.tab.height</code></td><td>数值；当前标签绘制尺寸</td></tr><tr><td><code>pogget.tab.hover</code>、<code>pogget.tab.selection</code></td><td>数值；悬停与选中动画进度</td></tr><tr><td><code>pogget.tab.pressed</code>、<code>pogget.tab.dragging</code></td><td>布尔；是否按下、是否拖动</td></tr></tbody></table><h2 id="搜索输入框-pogget-editor" tabindex="-1">搜索输入框 pogget.editor <a class="header-anchor" href="#搜索输入框-pogget-editor" aria-label="Permalink to &quot;搜索输入框 pogget.editor&quot;">​</a></h2><p>这里是标题/内联搜索的单行输入框，Markdown 多行编辑器见后文。</p><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.editor.x</code>、<code>pogget.editor.y</code></td><td>数值；输入框实际位置</td></tr><tr><td><code>pogget.editor.width</code>、<code>pogget.editor.height</code></td><td>数值；输入框实际尺寸</td></tr><tr><td><code>pogget.editor.text</code></td><td>文本；原生控件提供的显示文字</td></tr><tr><td><code>pogget.editor.placeholder</code></td><td>文本；占位文字</td></tr><tr><td><code>pogget.editor.focused</code></td><td>布尔；是否获得焦点</td></tr><tr><td><code>pogget.editor.selection</code></td><td>布尔；是否有选区</td></tr><tr><td><code>pogget.editor.cursor</code></td><td>数值；控件提供的光标绘制位置</td></tr><tr><td><code>pogget.editor.textWidth</code></td><td>数值；已测量文字宽度</td></tr><tr><td><code>pogget.editor.selectionStart</code>、<code>pogget.editor.selectionEnd</code></td><td>数值；选区绘制起止位置</td></tr><tr><td><code>pogget.editor.scroll</code></td><td>数值；水平滚动偏移</td></tr><tr><td><code>pogget.editor.caretAlpha</code></td><td>数值；光标闪烁不透明度</td></tr></tbody></table><h2 id="文件项目-pogget-fileicon" tabindex="-1">文件项目 pogget.fileIcon <a class="header-anchor" href="#文件项目-pogget-fileicon" aria-label="Permalink to &quot;文件项目 pogget.fileIcon&quot;">​</a></h2><p>这些输入在文件图标、文字、预览或拖动虚影的相应阶段逐项更新。普通无 slot 组件不会自动为所有文件重复绘制；应配合<a href="./slots.html#文件项目">文件项目绘制阶段</a>使用。</p><h3 id="几何与状态" tabindex="-1">几何与状态 <a class="header-anchor" href="#几何与状态" aria-label="Permalink to &quot;几何与状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.fileIcon.x</code>、<code>pogget.fileIcon.y</code></td><td>数值；原生文件项目位置</td></tr><tr><td><code>pogget.fileIcon.drawX</code>、<code>pogget.fileIcon.drawY</code></td><td>数值；当前绘制位置</td></tr><tr><td><code>pogget.fileIcon.size</code>、<code>pogget.fileIcon.height</code></td><td>数值；图标尺寸与项目高度</td></tr><tr><td><code>pogget.fileIcon.viewportWidth</code></td><td>数值；当前文件视口宽度</td></tr><tr><td><code>pogget.fileIcon.padding</code>、<code>pogget.fileIcon.spacing</code></td><td>数值；项目内边距与排列间距</td></tr><tr><td><code>pogget.fileIcon.customWidth</code></td><td>数值；自定义宽度，负值表示未指定</td></tr><tr><td><code>pogget.fileIcon.textSize</code></td><td>数值；当前文件名字号</td></tr><tr><td><code>pogget.fileIcon.wrapOverflow</code></td><td>数值；提前测量得到的文字换行溢出量</td></tr><tr><td><code>pogget.fileIcon.clipLeft</code>、<code>pogget.fileIcon.clipTop</code>、<code>pogget.fileIcon.clipRight</code>、<code>pogget.fileIcon.clipBottom</code></td><td>数值；原生交互单元裁切边界</td></tr><tr><td><code>pogget.fileIcon.list</code></td><td>布尔；当前项目按列表绘制</td></tr><tr><td><code>pogget.fileIcon.textPreview</code></td><td>布尔；当前使用文本预览</td></tr><tr><td><code>pogget.fileIcon.wrap</code></td><td>布尔；项目换行状态</td></tr><tr><td><code>pogget.fileIcon.clip</code></td><td>布尔；是否需要单元裁切</td></tr><tr><td><code>pogget.fileIcon.selected</code>、<code>pogget.fileIcon.hovered</code></td><td>布尔；是否选中、是否悬停</td></tr><tr><td><code>pogget.fileIcon.dimmed</code></td><td>布尔；当前项目是否应淡化</td></tr><tr><td><code>pogget.fileIcon.hover</code></td><td>数值；原生悬停动画进度</td></tr><tr><td><code>pogget.fileIcon.alpha</code>、<code>pogget.fileIcon.globalAlpha</code></td><td>数值；项目不透明度与全局不透明度输入</td></tr><tr><td><code>pogget.fileIcon.previewMode</code></td><td>数值；原生预览分类，供标准预设选择对应布局</td></tr><tr><td><code>pogget.fileIcon.ghost</code></td><td>布尔；当前调用是否绘制拖动虚影</td></tr><tr><td><code>pogget.fileIcon.network</code></td><td>布尔；是否为网络文本等网络项目</td></tr></tbody></table><h3 id="图像与拖入资源" tabindex="-1">图像与拖入资源 <a class="header-anchor" href="#图像与拖入资源" aria-label="Permalink to &quot;图像与拖入资源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.fileIcon.path</code></td><td>文本；当前文件路径，可交给 Shell 图标绘制</td></tr><tr><td><code>pogget.fileIcon.folder0</code>、<code>pogget.fileIcon.folder1</code>、<code>pogget.fileIcon.folder2</code>、<code>pogget.fileIcon.folder3</code></td><td>文本；原生筛选后的前四个目录条目路径，用于文件夹预览</td></tr><tr><td><code>pogget.fileIcon.folder</code></td><td>布尔；是否为文件夹</td></tr><tr><td><code>pogget.fileIcon.thumbnail</code></td><td>布尔；是否有媒体缩略图</td></tr><tr><td><code>pogget.fileIcon.thumbnailVisible</code></td><td>布尔；缩略图当前是否可见</td></tr><tr><td><code>pogget.fileIcon.media</code></td><td>数值；原生媒体分类，用于区分图片、视频、音频等布局</td></tr><tr><td><code>pogget.fileIcon.dragX</code>、<code>pogget.fileIcon.dragY</code></td><td>数值；拖动偏移</td></tr><tr><td><code>pogget.fileIcon.draggedCount</code></td><td>数值；外部拖入项目数量</td></tr></tbody></table><h3 id="文件名、搜索与预览" tabindex="-1">文件名、搜索与预览 <a class="header-anchor" href="#文件名、搜索与预览" aria-label="Permalink to &quot;文件名、搜索与预览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.fileIcon.title</code></td><td>文本；当前文件标题</td></tr><tr><td><code>pogget.fileIcon.detail</code></td><td>文本；原生已格式化的大小/日期等详情</td></tr><tr><td><code>pogget.fileIcon.drawTitle</code></td><td>文本；经过原生省略或布局测量后的绘制标题</td></tr><tr><td><code>pogget.fileIcon.font</code></td><td>文本；文件名字体族</td></tr><tr><td><code>pogget.fileIcon.detailType</code></td><td>数值；详情类别，<code>0</code> 大小、<code>1</code> 无、<code>2</code> 日期</td></tr><tr><td><code>pogget.fileIcon.colorMode</code></td><td>数值；文件名颜色策略，<code>0</code> 主题、<code>1</code> 白、<code>2</code> 黑</td></tr><tr><td><code>pogget.fileIcon.renderMode</code></td><td>数值；文件名阴影策略，<code>0..3</code> 对应无、厚、轻、主题</td></tr><tr><td><code>pogget.fileIcon.omitOffset</code></td><td>数值；原生文件名省略预算偏移</td></tr><tr><td><code>pogget.fileIcon.inlineView</code></td><td>布尔；是否在内联视图</td></tr><tr><td><code>pogget.fileIcon.gridWrap</code></td><td>布尔；网格文件名换行偏好</td></tr><tr><td><code>pogget.fileIcon.detailMeasuredWidth</code></td><td>数值；详情文字测量宽度</td></tr><tr><td><code>pogget.fileIcon.gridMeasuredHeight</code></td><td>数值；网格文字测量高度</td></tr><tr><td><code>pogget.fileIcon.searchActive</code></td><td>布尔；当前是否有搜索查询</td></tr><tr><td><code>pogget.fileIcon.searchExpanded</code></td><td>布尔；搜索展开状态</td></tr><tr><td><code>pogget.fileIcon.searchLayout</code></td><td>布尔；原生命中文本布局是否可用</td></tr><tr><td><code>pogget.fileIcon.searchMaxHeight</code></td><td>数值；搜索标题测量的高度预算</td></tr><tr><td><code>pogget.fileIcon.hitX</code>、<code>pogget.fileIcon.hitY</code>、<code>pogget.fileIcon.hitWidth</code>、<code>pogget.fileIcon.hitHeight</code></td><td>数值；本次查询命中片段的真实字形矩形，用于高亮绘制</td></tr><tr><td><code>pogget.fileIcon.markdown</code></td><td>布尔；当前预览是否为 Markdown</td></tr><tr><td><code>pogget.fileIcon.previewText</code></td><td>文本；宿主提供的文本预览摘要</td></tr><tr><td><code>pogget.fileIcon.previewTitle</code></td><td>文本；预览卡片标题</td></tr><tr><td><code>pogget.fileIcon.previewTitleMeasuredHeight</code></td><td>数值；预览标题实际测量高度</td></tr></tbody></table><h3 id="整体运动" tabindex="-1">整体运动 <a class="header-anchor" href="#整体运动" aria-label="Permalink to &quot;整体运动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.fileIcon.inputX</code>、<code>pogget.fileIcon.inputY</code></td><td>数值；传入运动公式的原始位置</td></tr><tr><td><code>pogget.fileIcon.push</code></td><td>数值；按压进度</td></tr><tr><td><code>pogget.fileIcon.deform</code></td><td>数值；排序形变进度</td></tr><tr><td><code>pogget.fileIcon.deformAxis</code></td><td>数值；排序形变轴</td></tr><tr><td><code>pogget.fileIcon.cursorX</code></td><td>数值；列表摆动使用的鼠标横坐标</td></tr><tr><td><code>pogget.fileIcon.pressX</code></td><td>数值；按压横坐标</td></tr></tbody></table><h2 id="内联导航与搜索" tabindex="-1">内联导航与搜索 <a class="header-anchor" href="#内联导航与搜索" aria-label="Permalink to &quot;内联导航与搜索&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.inlineNavigation</code></td><td>布尔；是否显示内联导航</td></tr><tr><td><code>pogget.inlineEditing</code></td><td>布尔；是否处于内联编辑模式</td></tr><tr><td><code>pogget.inlineNavigationOffset</code></td><td>数值；内联工具栏显隐的当前偏移</td></tr><tr><td><code>pogget.inlineAlpha</code></td><td>数值；内联界面不透明度</td></tr><tr><td><code>pogget.inlineColor</code></td><td>颜色；内联界面有效颜色</td></tr><tr><td><code>pogget.inlineAvailable</code></td><td>布尔；内联目标是否可用</td></tr><tr><td><code>pogget.inlinePendingExit</code></td><td>布尔；是否等待退出内联视图</td></tr><tr><td><code>pogget.inlineSearch</code></td><td>布尔；当前是否使用内联搜索界面</td></tr><tr><td><code>pogget.inlineNavigationBack.hover</code></td><td>数值；内联后退按钮悬停进度</td></tr><tr><td><code>pogget.inlineNavigationHome.hover</code></td><td>数值；内联主页按钮悬停进度</td></tr><tr><td><code>pogget.inlineNavigationSave.hover</code></td><td>数值；内联保存按钮悬停进度</td></tr><tr><td><code>pogget.inlineNavigationOpen.hover</code></td><td>数值；内联外部打开按钮悬停进度</td></tr><tr><td><code>pogget.inlineNavigationSearch.hover</code></td><td>数值；内联搜索按钮悬停进度</td></tr><tr><td><code>pogget.inlineSearchBack.hover</code></td><td>数值；内联搜索返回按钮悬停进度</td></tr><tr><td><code>pogget.inlineSearchCancel.hover</code></td><td>数值；内联搜索取消按钮悬停进度</td></tr></tbody></table><h2 id="内联内容-pogget-inlinecontent" tabindex="-1">内联内容 pogget.inlineContent <a class="header-anchor" href="#内联内容-pogget-inlinecontent" aria-label="Permalink to &quot;内联内容 pogget.inlineContent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.inlineContent.width</code>、<code>pogget.inlineContent.height</code></td><td>数值；内联内容的宿主尺寸</td></tr><tr><td><code>pogget.inlineContent.startX</code>、<code>pogget.inlineContent.startY</code></td><td>数值；展开动画起始位置</td></tr><tr><td><code>pogget.inlineContent.startWidth</code>、<code>pogget.inlineContent.startHeight</code></td><td>数值；展开动画起始尺寸</td></tr><tr><td><code>pogget.inlineContent.progress</code></td><td>数值；进入/退出动画进度</td></tr><tr><td><code>pogget.inlineContent.switchProgress</code></td><td>数值；层级切换动画进度</td></tr><tr><td><code>pogget.inlineContent.titleOffset</code></td><td>数值；标题占位偏移</td></tr><tr><td><code>pogget.inlineContent.color</code></td><td>颜色；内容遮罩有效颜色</td></tr><tr><td><code>pogget.inlineContent.compatible</code></td><td>数值；内联内容使用的兼容/渲染层</td></tr><tr><td><code>pogget.inlineContent.visible</code></td><td>布尔；内容是否可见</td></tr><tr><td><code>pogget.inlineContent.exiting</code>、<code>pogget.inlineContent.switching</code></td><td>布尔；是否退出、是否切换层级</td></tr><tr><td><code>pogget.inlineContent.exitSnapshot</code>、<code>pogget.inlineContent.switchSnapshot</code></td><td>布尔；退出/切换快照是否可用</td></tr><tr><td><code>pogget.inlineContent.search</code></td><td>布尔；内联搜索状态</td></tr><tr><td><code>pogget.inlineContent.searchChrome</code></td><td>布尔；是否使用内联搜索配套布局</td></tr><tr><td><code>pogget.inlineContent.searchExtraY</code></td><td>数值；搜索布局对结果区增加的纵向占位</td></tr><tr><td><code>pogget.inlineContent.scrollDepth</code></td><td>数值；当前滚动深度</td></tr><tr><td><code>pogget.inlineContent.upward</code></td><td>布尔；当前内联布局是否向上展开</td></tr></tbody></table><h2 id="markdown-编辑器-pogget-markdowneditor" tabindex="-1">Markdown 编辑器 pogget.markdownEditor <a class="header-anchor" href="#markdown-编辑器-pogget-markdowneditor" aria-label="Permalink to &quot;Markdown 编辑器 pogget.markdownEditor&quot;">​</a></h2><p>这些输入在布局与相应绘制请求时更新。正文通过命名内容资源绘制；这些接口不开放脚本或 Markdown 语义内部样式。</p><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.markdownEditor.width</code>、<code>pogget.markdownEditor.height</code></td><td>数值；控件尺寸</td></tr><tr><td><code>pogget.markdownEditor.x</code>、<code>pogget.markdownEditor.y</code></td><td>数值；绘制请求的位置</td></tr><tr><td><code>pogget.markdownEditor.zoom</code></td><td>数值；原生用户缩放输入，适合定义自定义视口倍率</td></tr><tr><td><code>pogget.markdownEditor.layoutZoom</code></td><td>数值；布局使用的缩放值</td></tr><tr><td><code>pogget.markdownEditor.layoutScale</code></td><td>数值；布局采用的实际倍率</td></tr><tr><td><code>pogget.markdownEditor.scale</code></td><td>数值；本次内容绘制的实际倍率</td></tr><tr><td><code>pogget.markdownEditor.drawX</code>、<code>pogget.markdownEditor.drawY</code></td><td>数值；内容实际绘制原点</td></tr><tr><td><code>pogget.markdownEditor.masterAlpha</code></td><td>数值；本次绘制的整体不透明度</td></tr><tr><td><code>pogget.markdownEditor.textWidth</code>、<code>pogget.markdownEditor.textHeight</code></td><td>数值；正文真实测量尺寸</td></tr><tr><td><code>pogget.markdownEditor.nativeMargin</code>、<code>pogget.markdownEditor.nativeTextSize</code></td><td>数值；原生默认边距与字号</td></tr><tr><td><code>pogget.markdownEditor.wrap</code></td><td>布尔；是否换行</td></tr><tr><td><code>pogget.markdownEditor.nativeRadius</code>、<code>pogget.markdownEditor.nativeBorder</code></td><td>数值；原生圆角与边框宽度</td></tr><tr><td><code>pogget.markdownEditor.nativeBgAlpha</code>、<code>pogget.markdownEditor.nativeBorderAlpha</code></td><td>数值；原生背景、边框不透明度</td></tr><tr><td><code>pogget.markdownEditor.background</code>、<code>pogget.markdownEditor.textColor</code>、<code>pogget.markdownEditor.borderColor</code></td><td>颜色；当前有效背景、文字、边框色</td></tr><tr><td><code>pogget.markdownEditor.scrollX</code>、<code>pogget.markdownEditor.scrollY</code></td><td>数值；横纵滚动偏移</td></tr><tr><td><code>pogget.markdownEditor.caretX</code>、<code>pogget.markdownEditor.caretY</code>、<code>pogget.markdownEditor.caretHeight</code></td><td>数值；真实光标位置与高度</td></tr><tr><td><code>pogget.markdownEditor.caretOpacity</code></td><td>数值；光标不透明度</td></tr><tr><td><code>pogget.markdownEditor.selectionX</code>、<code>pogget.markdownEditor.selectionY</code>、<code>pogget.markdownEditor.selectionWidth</code>、<code>pogget.markdownEditor.selectionHeight</code></td><td>数值；本次选区片段矩形，来自真实字形测量</td></tr><tr><td><code>pogget.markdownEditor.placeholder</code></td><td>文本；占位文字</td></tr><tr><td><code>pogget.markdownEditor.hintOpacity</code></td><td>数值；缩放提示不透明度</td></tr><tr><td><code>pogget.markdownEditor.staticText</code></td><td>布尔；是否以静态文本模式显示</td></tr><tr><td><code>pogget.markdownEditor.editing</code></td><td>布尔；是否正在编辑</td></tr><tr><td><code>pogget.markdownEditor.selected</code></td><td>布尔；是否有选区</td></tr><tr><td><code>pogget.markdownEditor.hasLayout</code></td><td>布尔；正文布局是否可用</td></tr><tr><td><code>pogget.markdownEditor.verticalHover</code>、<code>pogget.markdownEditor.horizontalHover</code></td><td>布尔；竖向/横向滚动条是否悬停</td></tr><tr><td><code>pogget.markdownEditor.verticalDrag</code>、<code>pogget.markdownEditor.horizontalDrag</code></td><td>布尔；竖向/横向滚动条是否拖动</td></tr><tr><td><code>pogget.markdownEditor.zoomEnabled</code></td><td>布尔；是否启用缩放</td></tr></tbody></table><p>自定义视口请以 <code>zoom</code> 为独立输入。<code>scale</code>、<code>drawX</code>、<code>drawY</code>、<code>layoutScale</code> 是已经计算后的输出事实，不能反向用来定义自身视口，否则会形成布局反馈。</p><h2 id="分页指示器-pogget-pageindicator" tabindex="-1">分页指示器 pogget.pageIndicator <a class="header-anchor" href="#分页指示器-pogget-pageindicator" aria-label="Permalink to &quot;分页指示器 pogget.pageIndicator&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.pageIndicator.width</code>、<code>pogget.pageIndicator.height</code></td><td>数值；分页指示器宿主尺寸</td></tr><tr><td><code>pogget.pageIndicator.count</code></td><td>数值；真实页数</td></tr><tr><td><code>pogget.pageIndicator.position</code></td><td>数值；当前页的动画位置</td></tr><tr><td><code>pogget.pageIndicator.visible</code></td><td>布尔；是否需要显示</td></tr><tr><td><code>pogget.pageIndicator.vertical</code></td><td>布尔；是否纵向排列</td></tr><tr><td><code>pogget.pageIndicator.index</code></td><td>数值；当前重复点序号，Surface 和 Active 阶段为 <code>0</code></td></tr></tbody></table><h2 id="整盒收尾-pogget-containerframe" tabindex="-1">整盒收尾 pogget.containerFrame <a class="header-anchor" href="#整盒收尾-pogget-containerframe" aria-label="Permalink to &quot;整盒收尾 pogget.containerFrame&quot;">​</a></h2><p>这里的像素宽高和 <code>scale</code> 是显式例外：需要通过 <code>widthPixels / scale</code>、<code>heightPixels / scale</code> 换算为 DIP。</p><table tabindex="0"><thead><tr><th>输入</th><th>类型与用途</th></tr></thead><tbody><tr><td><code>pogget.containerFrame.widthPixels</code>、<code>pogget.containerFrame.heightPixels</code></td><td>数值；客户区实际像素宽高</td></tr><tr><td><code>pogget.containerFrame.scale</code></td><td>数值；像素到 DIP 的缩放因子</td></tr><tr><td><code>pogget.containerFrame.mode</code>、<code>pogget.containerFrame.frame</code></td><td>数值；本次收尾的渲染层和边框模式</td></tr><tr><td><code>pogget.containerFrame.nativeRadius</code></td><td>数值；原生窗口圆角</td></tr><tr><td><code>pogget.containerFrame.background</code></td><td>颜色；窗口有效背景色</td></tr><tr><td><code>pogget.containerFrame.borderColor</code></td><td>颜色；窗口有效边框色</td></tr><tr><td><code>pogget.containerFrame.borderOpacity</code></td><td>数值；边框不透明度</td></tr><tr><td><code>pogget.containerFrame.customBorder</code></td><td>布尔；是否启用自定义边框色</td></tr><tr><td><code>pogget.containerFrame.pointerX</code>、<code>pogget.containerFrame.pointerY</code></td><td>数值；原生追踪的指针位置，用于光效</td></tr><tr><td><code>pogget.containerFrame.spotlight</code></td><td>数值；原生聚光反馈值</td></tr><tr><td><code>pogget.containerFrame.tag</code></td><td>布尔；是否有标签着色上下文</td></tr><tr><td><code>pogget.containerFrame.tagColor</code></td><td>颜色；标签着色颜色</td></tr><tr><td><code>pogget.containerFrame.upward</code></td><td>布尔；向上展开方向</td></tr></tbody></table><p>以上输入与 <code>PersonalizationInputs.hpp</code> 的完整类型表，以及运行时各上下文提交点核对（2026-11-08）。重复项、搜索布局、缩略图和快照只在对应调用中有效，不是可任意查询所有文件或保留资源的接口。</p>',42)]))}const b=d(c,[["render",g]]);export{s as __pageData,b as default};
